package hexadecimal

// maxInt64 is the largest value representable by an int64. It is defined
// locally so the conversion below stays self-contained (first principles,
// no dependency on the standard library).
const maxInt64 = 9223372036854775807

// SyntaxError is returned when the input is not a valid hexadecimal string
// (empty, or containing a character that is not a hexadecimal digit).
type SyntaxError struct {
	Value string
}

func (e SyntaxError) Error() string {
	return "syntax error: " + e.Value + " is not a valid hexadecimal number"
}

// RangeError is returned when the input is a valid hexadecimal string whose
// value exceeds the range of int64.
type RangeError struct {
	Value string
}

func (e RangeError) Error() string {
	return "range error: " + e.Value + " is out of range for int64"
}

// hexValue returns the decimal value of a single hexadecimal digit, or -1 if
// the byte is not a valid hexadecimal digit.
func hexValue(c byte) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c-'a') + 10
	case c >= 'A' && c <= 'F':
		return int(c-'A') + 10
	}
	return -1
}

// ParseHex converts a hexadecimal number, represented as a string (e.g.
// "10af8c"), to its decimal equivalent using first principles.
//
// It returns a SyntaxError for empty or malformed input and a RangeError when
// the value would not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, SyntaxError{in}
	}

	var result int64
	for i := 0; i < len(in); i++ {
		d := hexValue(in[i])
		if d < 0 {
			return 0, SyntaxError{in}
		}
		// Detect overflow before it happens: result*16 + d would exceed
		// maxInt64 exactly when result > (maxInt64 - d) / 16.
		if result > (maxInt64-int64(d))/16 {
			return 0, RangeError{in}
		}
		result = result*16 + int64(d)
	}
	return result, nil
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching list
// of error cases: "none", "syntax", or "range".
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		switch err.(type) {
		case nil:
			results[i] = "none"
		case SyntaxError:
			results[i] = "syntax"
		case RangeError:
			results[i] = "range"
		default:
			results[i] = "syntax"
		}
	}
	return results
}
